70: // NewWithContext creates new Progress container instance with provided
71: // context. It's not possible to reuse instance after `(*Progress).Wait`
72: // method has been called.
73: func NewWithContext(ctx context.Context, options ...ContainerOption) *Progress {
74: 	if ctx == nil {
75: 		ctx = context.Background()
76: 	}
77: 	ctx, cancel := context.WithCancel(ctx)
78: 
79: 	s := &pState{
80: 		hmQueueLen:  defaultHmQueueLength,
81: 		renderReq:   make(chan time.Time),
82: 		popPriority: math.MinInt32,
83: 		refreshRate: defaultRefreshRate,
84: 		queueBars:   make(map[*Bar]*queueBar),
85: 		output:      os.Stdout,
86: 		debugOut:    io.Discard,
87: 	}
